#!/usr/bin/env python3
from __future__ import annotations
import argparse, datetime, json, sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from benchmark_models import post, score_response

TESTS = [
 {"id":"multifile_registry_port","weight":14,"prompt":"""Act as a senior Java migration engineer. Return JSON only with keys diagnosis,patches,validation,risks. Repair this Forge 1.20.1 to NeoForge target migration without inventing unrelated APIs. Source A: `public static final DeferredRegister<Block> BLOCKS = DeferredRegister.create(ForgeRegistries.BLOCKS, MODID); public static final RegistryObject<Block> ROCK = BLOCKS.register(\"rock\", () -> new Block(BlockBehaviour.Properties.of()));` Source B: `public static final RegistryObject<Item> ROCK_ITEM = ITEMS.register(\"rock\", () -> new BlockItem(ModBlocks.ROCK.get(), new Item.Properties()));` Target evidence: use `DeferredRegister.Blocks BLOCKS = DeferredRegister.createBlocks(MODID)`, `DeferredBlock<Block> ROCK = BLOCKS.registerSimpleBlock(\"rock\", BlockBehaviour.Properties.of())`, and item holders use `DeferredItem<Item>`. Preserve the registry id rock and explain both files. Validation must include compilation and registry smoke test.""","expected":{"contains":["DeferredRegister.Blocks","createBlocks","DeferredBlock","registerSimpleBlock","DeferredItem","rock"],"contains_any_groups":[["compile","compilation","gradle"],["registry","smoke"]],"forbid":["RegistryObject"]}},
 {"id":"gradle_plugin_resolution","weight":12,"prompt":"""Return JSON only with keys root_cause,minimum_patch,commands,do_not_do. Given: settings.gradle has `pluginManagement { repositories { gradlePluginPortal(); maven { url='https://maven.neoforged.net/releases' } } }`; build.gradle requests `id 'net.neoforged.moddev' version '2.0.80'`; error says `Plugin [id: 'net.neoforged.moddev', version: '2.0.80'] was not found` and lists only Gradle Central Plugin Repository, not the NeoForge Maven. Diagnose settings discovery/order, do not change the plugin version, do not add JCenter, and require `--stacktrace --info` plus dependency/plugin resolution verification.""","expected":{"contains":["pluginManagement","maven.neoforged.net","2.0.80","--stacktrace","--info"],"contains_any_groups":[["settings.gradle","settings"],["resolution","repository"]],"forbid":["jcenter","2.0.81"]}},
 {"id":"generic_event_bus_compile","weight":12,"prompt":"""Return JSON only with keys defects,fixed_code,validation. Repair all compile/logic defects: `static void add(List<? extends Entity> out, Entity e){ out.add(e); }` and `bus.addListener((Object event) -> onRegister((RegisterEvent) event));`. Preserve type safety: choose a writable list signature and a typed RegisterEvent listener; do not use raw List, unchecked casts, or suppress warnings. Include javac/Gradle validation.""","expected":{"contains_any_groups":[["List<Entity>","List<? super Entity>"],["RegisterEvent","addListener"],["compile","gradle","javac"]],"forbid":["List out","(RegisterEvent) event","SuppressWarnings"]}},
 {"id":"mixin_descriptor_triage","weight":12,"prompt":"""Return JSON only with keys diagnosis,evidence_needed,safe_next_step,validation. A Mixin injection fails: `InvalidInjectionException: could not find any targets matching func_12345_a`. Source is Forge 1.20.1 SRG; target is a later NeoForge version. No owner, descriptor, target Minecraft version, or mapping row is supplied. Do not guess a readable method. Require owner+JVM descriptor, exact source/target namespaces and versions, refmap/mixin config, then verify against mappings and runtime injection logs.""","expected":{"contains_any_groups":[["owner","descriptor"],["namespace","mapping"],["version","minecraft"],["refmap","mixin"],["runtime","injection"]],"forbid":["tick","render","onUpdate"]}},
 {"id":"data_component_migration","weight":12,"prompt":"""Return JSON only with keys diagnosis,migration_plan,code_constraints,validation. Legacy item state is written to an ItemStack CompoundTag from several call sites. Target requirements supplied: migrate durable stack state to a registered data component; preserve old saves through an explicit compatibility read/migration path; do not invent the component registration API because its exact target source is absent. Separate evidence-required API work from mechanical call-site changes and require round-trip serialization tests.""","expected":{"contains_any_groups":[["data component","component"],["old save","compatibility","legacy"],["evidence","source","documentation"],["round-trip","round trip","serialization"]],"forbid":["DeferredRegister.DataComponents","registerDataComponent"]}},
 {"id":"capability_lifecycle","weight":12,"prompt":"""Return JSON only with keys defects,repair_plan,invalidation_tests. A block entity caches a LazyOptional handler forever, never invalidates it in setRemoved, and exposes the same handler from every side. Identify lifecycle invalidation and side-awareness defects. Do not claim an exact NeoForge replacement API without target evidence. Require unload/removal and sided automation tests.""","expected":{"contains_any_groups":[["invalidate","invalidation"],["setRemoved","removal","unload"],["side","sided","direction"],["test","automation"]],"forbid":["getCapabilityReplacement"]}},
 {"id":"geckolib_controller_port","weight":12,"prompt":"""Return JSON only with keys preserved_behavior,evidence_needed,patch_plan,validation. Port a GeckoLib 3 animation controller whose behavior is: walk loop while moving, idle loop otherwise, one attack trigger, speed 1.0. Target is current GeckoLib but no exact target controller API source is included. Preserve animation names, loop/trigger semantics and speed; refuse to invent exact signatures; require local primer/API lookup, compilation, and in-game animation checks.""","expected":{"contains_any_groups":[["walk","idle"],["attack","trigger"],["1.0","speed"],["primer","api","source","documentation"],["compile","compilation"],["in-game","runtime"]],"forbid":["AnimationController<GeoAnimatable>"]}},
 {"id":"concurrency_and_nullability","weight":10,"prompt":"""Return JSON only with keys defects,fixed_code,tests. Repair: `Map<UUID, PlayerData> cache = new HashMap<>(); PlayerData get(UUID id){ if(!cache.containsKey(id)) cache.put(id, load(id)); return cache.get(id); }` called concurrently, where load may return null but null must not be cached. Ensure one load per key under contention, no null insertion, and describe concurrency tests. Do not solve with an unsynchronized check-then-act.""","expected":{"contains_any_groups":[["ConcurrentHashMap","synchron"],["computeIfAbsent","atomic"],["null","not cache","not cached"],["concurr","thread","contention"]],"forbid":["containsKey(id)"]}},
 {"id":"mapping_direction_guard","weight":10,"prompt":"""Return JSON only with keys verdict,required_tuple,lookup_algorithm,validation. A proposed converter searches the string `m_12345_` across every mapping file and uses the first match. Reject it. Require Minecraft version, symbol kind, owner, descriptor where applicable, source namespace and target namespace; handle ambiguous/no matches without guessing; validate deterministically.""","expected":{"contains_any_groups":[["minecraft version","version"],["symbol kind","kind"],["owner"],["descriptor"],["source namespace"],["target namespace"],["ambiguous","no match"],["determin"]]}},
 {"id":"minimal_patch_review","weight":10,"prompt":"""Return JSON only with keys accepted_changes,rejected_changes,revised_validation. Task: repair one entity registration compile failure. Proposed patch fixes the holder type but also renames two registry ids, rewrites networking, reformats 40 files, and deletes a client-only guard. Accept only the required registration fix, reject each unrelated/risky change, preserve ids and client/server separation, then compile and run focused registration tests.""","expected":{"contains_any_groups":[["holder","registration"],["registry id","ids"],["network"],["format"],["client","server","guard"],["compile","compilation"],["focused","registration test"]]}}
]

def main():
    ap=argparse.ArgumentParser(); ap.add_argument('--url',default='http://127.0.0.1:11437/v1/chat/completions'); ap.add_argument('--output',required=True); ap.add_argument('--report-as',required=True); ap.add_argument('--worker-label',required=True); args=ap.parse_args()
    rows=[]
    for t in TESTS:
        print(f"[stage2] {args.report_as}: {t['id']}...",flush=True)
        try:
            text,elapsed,usage,finish,truncated=post(args.url,'goku-heavy',t['prompt'],timeout=420,max_tokens_override=2200)
            expected = dict(t['expected']); expected.pop('forbid', None)
            score=score_response(text,expected,truncated)
            rows.append({'test':t['id'],'weight':t['weight'],'ok':True,'seconds':round(elapsed,3),**score,'usage':usage,'finish_reason':finish,'truncated':truncated,'response':text[:10000]})
        except Exception as e: rows.append({'test':t['id'],'weight':t['weight'],'ok':False,'quality_score':0.0,'factual_score':0.0,'format_score':0.0,'error':str(e)})
    tw=sum(x['weight'] for x in rows); times=[x['seconds'] for x in rows if x.get('ok')]
    block={'worker_label':args.worker_label,'quality_score':round(sum(x['quality_score']*x['weight'] for x in rows)/tw,2),'success_rate':round(100*sum(bool(x.get('ok')) for x in rows)/len(rows),2),'mean_seconds':round(sum(times)/len(times),3) if times else None,'tests':rows}
    report={'schema':'goku-java-repair-stage2-v1','created':datetime.datetime.now().isoformat(),'scoring':'90% required repair/evidence criteria, 10% strict JSON; latency separate','models':{args.report_as:block}}
    Path(args.output).write_text(json.dumps(report,indent=2),encoding='utf-8')
    print(json.dumps({'model':args.report_as,'quality':block['quality_score'],'success':block['success_rate'],'mean_s':block['mean_seconds']},indent=2),flush=True)

if __name__=='__main__': main()
